{
  "versao": "1-ia-sozinha",
  "anotacoes": [
    {
      "trecho_id": "ACTION_LOG.A01",
      "rotulo": "CORRETO",
      "informacoes": [],
      "observacao": "A entrega do redutor permanece prevista para D20."
    },
    {
      "trecho_id": "ACTION_LOG.A02",
      "rotulo": "CORRETO",
      "informacoes": [],
      "observacao": "O desenho CAD revisão 1 continua sendo gerado em D10."
    },
    {
      "trecho_id": "ACTION_LOG.A03",
      "rotulo": "CORRETO",
      "informacoes": [],
      "observacao": "A análise estrutural termina em D14, data do Design Freeze."
    },
    {
      "trecho_id": "ACTION_LOG.A04",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "a partir de D25",
          "motivo": "valor_divergente",
          "correto_seria": "A reserva deve começar em D28, quando o protótipo fica disponível."
        },
        {
          "citacao": "até a validação em D35",
          "motivo": "valor_divergente",
          "correto_seria": "A validação fica concluída em D38."
        },
        {
          "citacao": "o protótipo estará disponível em D26",
          "motivo": "valor_divergente",
          "correto_seria": "O protótipo fica disponível em D28."
        }
      ],
      "observacao": "O período atualizado entre protótipo e validação continua sendo de 10 dias."
    },
    {
      "trecho_id": "ACTION_LOG.A05",
      "rotulo": "CORRETO",
      "informacoes": [],
      "observacao": "O limite de D40 e o custo de R$ 300 por dia excedente permanecem válidos."
    },
    {
      "trecho_id": "ACTION_LOG.A06",
      "rotulo": "DECISAO_HUMANA",
      "informacoes": [],
      "observacao": "As novas datas de entrega podem mudar quais peças cabem na janela de frete consolidado; cabe avaliar a ação."
    },
    {
      "trecho_id": "RISK_REGISTER.R01",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "não tem folga",
          "motivo": "valor_divergente",
          "correto_seria": "O redutor tem 3 dias de folga: a montagem está prevista para D23 e a entrega do redutor em D20."
        },
        {
          "citacao": "qualquer atraso empurraria a montagem para depois de D20 e a liberação para depois de D40",
          "motivo": "premissa_alterada",
          "correto_seria": "Atrasos de até 3 dias na entrega do redutor não deslocariam a montagem. A montagem está prevista para D23 e a liberação de engenharia para D43."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "RISK_REGISTER.R02",
      "rotulo": "DECISAO_HUMANA",
      "informacoes": [],
      "observacao": "O atraso comunicado ocorreu e deslocou a montagem e a validação; cabe avaliar o tratamento do risco."
    },
    {
      "trecho_id": "RISK_REGISTER.R03",
      "rotulo": "DECISAO_HUMANA",
      "informacoes": [],
      "observacao": "A extensão do teste continua podendo gerar os custos descritos, mas o risco deve ser avaliado à luz do cronograma atualizado."
    },
    {
      "trecho_id": "RISK_REGISTER.R04",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "como compras e fabricação não têm folga, cada dia de reanálise adiaria a liberação",
          "motivo": "premissa_alterada",
          "correto_seria": "Há até 3 dias de folga antes de compras e fabricação deslocarem a montagem; uma reanálise de até 3 dias não adiaria a liberação."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "RISK_REGISTER.R05",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "com mais 3 dias, ele terminaria em D31",
          "motivo": "valor_divergente",
          "correto_seria": "O ensaio de vedação termina em D31; se repetido integralmente com mais 3 dias, termina em D34."
        },
        {
          "citacao": "validação em D35",
          "motivo": "valor_divergente",
          "correto_seria": "A validação fica concluída em D38."
        }
      ],
      "observacao": "Mesmo repetido, o ensaio terminaria antes da validação e não afetaria o prazo."
    },
    {
      "trecho_id": "RISK_REGISTER.R06",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "Se a peça só ficar disponível depois de D20, a montagem começaria depois da data planejada e o fim do projeto seria adiado na mesma medida.",
          "motivo": "premissa_alterada",
          "correto_seria": "A montagem está prevista para D23. Como o acoplamento está disponível desde D18, só uma disponibilidade posterior a D23 deslocaria a montagem e o fim do projeto."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "DECISION_LOG.D01",
      "rotulo": "PRESERVAR",
      "informacoes": [],
      "observacao": "Registro histórico de decisão."
    },
    {
      "trecho_id": "DECISION_LOG.D02",
      "rotulo": "PRESERVAR",
      "informacoes": [],
      "observacao": "Registro histórico de decisão."
    },
    {
      "trecho_id": "DECISION_LOG.D03",
      "rotulo": "PRESERVAR",
      "informacoes": [],
      "observacao": "Registro histórico de decisão."
    },
    {
      "trecho_id": "DECISION_LOG.D04",
      "rotulo": "PRESERVAR",
      "informacoes": [],
      "observacao": "Registro histórico de decisão."
    }
  ]
}
